// julia inspiration taken from https://www.shadertoy.com/view/Ndcczj
// mangled

#define ITER_MAX 1024
#define ITER_DEL 0.0025

vec3 normalMap(vec2 uv) {
    float e = 0.001;
    float h1 = length(uv);
    float h2 = length(uv + vec2(e, 0.0));
    float h3 = length(uv + vec2(0.0, e));

    vec3 normal = normalize(vec3(h1 - h2, h1 - h3, e));
    return normal * 0.5 + 0.5;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 auv = fragCoord.xy / iResolution.xy;
    vec2 uv = ((2.0 * fragCoord - iResolution.xy) / iResolution.y) * 1.2;

    float l = 0.0;
    for (int i = 0; i < ITER_MAX; ++i) {
        l += ITER_DEL;
        uv = vec2(uv.x * uv.x - uv.y * uv.y, uv.x * uv.y) + vec2(sin(128.0 + iTime / 29.0), cos(iTime / 23.0));
        if (dot(uv, uv) > float(ITER_MAX)) break;
    }

    // make this /uv.x and /uv.x for "round" forms
    vec3 lightDir = normalize(vec3(cos(-iTime) / uv.x, sin(-iTime) / uv.y, 0.02));
    vec3 normal = normalMap(uv * 0.25);
    float spec = pow(max(dot(normal, lightDir), 0.0), 8.0);
    float spec2 = pow(max(dot(normal, lightDir.yzx * 1.1), 0.0), 6.0);
    float spec3 = pow(max(dot(normal, lightDir.zxy * 0.9), 0.0), 6.0);
    vec3 color = vec3(spec * 0.25);
    color += spec2 * vec3(0.2, 0.4, 0.7);
    color += spec3 * vec3(0.9, 0.5, 0.0);
    fragColor = vec4(color, 1.0);
}
